/** sources.item@1.0.0 (owner: sources) */
/**
 * One thing a source said, with its provenance: source, canonical URL, retrieval time, content hash, raw-body hash, parser version and the terms it was ingested under. A field the source did not state is null — never guessed. Items change only through successful fetches (a new revision per content change) or an explicit, audited removal.
 */
export interface SourceItem {
  id: string;
  source_key: string;
  category: "news" | "blog" | "reviews" | "deals" | "coupons" | "trade";
  /**
   * article | url | sitemap | product | offer | review | review_signal | record | coupon …
   */
  kind: string;
  /**
   * The source's own id (guid, @id, API id) or the canonical URL.
   */
  identity: string;
  canonical_url: string | null;
  title: string | null;
  /**
   * Plain text, capped. Sources keeps metadata and short descriptions, not republishable full text.
   */
  summary: string | null;
  authors: string[];
  published_at: string | null;
  source_updated_at: string | null;
  /**
   * Adapter-specific parsed fields (offers, ratings, prices as stated, API extras).
   */
  fields: {};
  revision: number;
  provenance: {
    /**
     * Last successful fetch that contained this item (observation time).
     */
    retrieved_at: string;
    first_seen_at: string;
    content_hash: string;
    raw_body_hash: string | null;
    parser_version: string;
    fetch_run_id: string | null;
    license_note: string | null;
    terms_note: string | null;
    /**
     * Principal that entered a manual item.
     */
    entered_by: string | null;
  };
  removed: {
    at: string;
    reason: string;
  } | null;
  change_seq?: number;
  revisions?: unknown[];
}

/** mods.mod-manifest@1.0.0 (owner: contracts) */
/**
 * A mod as the platform knows it (ADR-013): who publishes it, which runtime runs it, which capabilities it asks for and the resources it may use. Requested capabilities are only a request: the install's approved subset is the grant, and trust tiers are install metadata that never change a grant check. The runtime-specific payload (a data pack, a script bundle) is not part of the manifest.
 */
export interface ModManifest {
  /**
   * Stable mod id; its principal subject is mod:<id>.
   */
  id: string;
  name: string;
  /**
   * Semantic version of this release.
   */
  version: string;
  description?: string;
  publisher: SubjectRef;
  /**
   * Where the mod runs: <service>.<surface>, e.g. games.browser, games.source, live.overlay.
   */
  target: string;
  /**
   * Runtime adapter and its major version, e.g. games-content@1 (declarative data pack) or source-quickjs@1.
   */
  runtime: string;
  permissions: {
    /**
     * Capability ids the mod asks for (3+ segments). The target runtime binds only those it implements, and only once granted.
     *
     * @maxItems 64
     */
    capabilities: string[];
    /**
     * Event types the mod wants delivered to it.
     *
     * @maxItems 64
     */
    events?: string[];
    /**
     * User-module namespaces the mod wants to read or write (a trailing .* names a family).
     *
     * @maxItems 32
     */
    modules?: string[];
    /**
     * Media namespaces the mod wants to read or write.
     *
     * @maxItems 32
     */
    mediaNamespaces?: string[];
  };
  /**
   * The budget the mod asks for. Runtimes meter it; the sandbox that enforces it lives in OpenVibe.Host (Stage C).
   */
  resources: {
    /**
     * CPU milliseconds per tick (game runtimes) or per request.
     */
    cpuMs: number;
    memoryMb: number;
    storageMb: number;
    /**
     * Hosts the mod may reach over the network. Empty or absent = none.
     *
     * @maxItems 32
     */
    outboundHosts?: string[];
  };
  /**
   * Assets the mod ships, as Media object references.
   *
   * @maxItems 256
   */
  assets?: MediaRef[];
  compatibility: {
    /**
     * Semver range of the runtime this release works with, e.g. ">=1.0.0 <2.0.0".
     */
    runtime: string;
    /**
     * Semver range of openvibe-contracts releases it was built against.
     */
    contracts?: string;
  };
  homepage?: string;
}

/** codes.app-manifest@1.0.0 (owner: codes) */
/**
 * PROPOSAL (OpenVibe.Codes, roadmap Wave 20): an app release as the platform knows it. The app is a Network developer app (ADR-014): its id is the Network app id, its capabilities are only a request (the grants in Network are the authority), and trust tiers are metadata that never change a grant check. OpenVibe.Codes validates with this schema, loaded into openvibe-contracts' validator, until Contracts publishes it as codes.app-manifest@1.
 */
export interface AppManifest {
  /**
   * The Network app id (its client_id). Its principal subject is app:<id>.
   */
  id: string;
  name: string;
  /**
   * Semantic version of this release.
   */
  version: string;
  description?: string;
  publisher: SubjectRef;
  /**
   * The Network project that owns the app. Tenancy in other services is keyed by it (ADR-014).
   */
  project_id: string;
  /**
   * The app's environment. Apps never change environment.
   */
  environment?: "sandbox" | "production";
  /**
   * Capability ids the app asks for (3+ segments). Only active public (or partner, by staff allowance) capabilities can ever be granted to apps.
   *
   * @maxItems 64
   */
  capabilities: string[];
  events?: {
    /**
     * Event types (or a trailing .* family) the app subscribes to.
     *
     * @maxItems 64
     */
    consumes?: string[];
  };
  /**
   * Informational copy of the redirect URIs registered in Network (Network's list is the authority).
   *
   * @maxItems 10
   */
  redirect_uris?:
    | []
    | [string]
    | [string, string]
    | [string, string, string]
    | [string, string, string, string]
    | [string, string, string, string, string]
    | [string, string, string, string, string, string]
    | [string, string, string, string, string, string, string]
    | [string, string, string, string, string, string, string, string]
    | [string, string, string, string, string, string, string, string, string]
    | [string, string, string, string, string, string, string, string, string, string];
  homepage?: string;
  repository?: string;
  /**
   * SPDX license expression.
   */
  license?: string;
  compatibility: {
    /**
     * Semver range of openvibe-contracts releases it was built against.
     */
    contracts: string;
    /**
     * Semver range of openvibe-sdk releases it uses.
     */
    sdk?: string;
  };
}

/** events.redaction-directive@1.0.0 (owner: events) */
/**
 * payload.redacts (ADR-026): a producer takes back events it published earlier. Any event may carry it, normally the producer's own *.deleted event. It names event_ids, or subject_type + subject_ids, or both, never an empty list. event_ids names events directly; subject_type + subject_ids names every stored event of the same source (for an app, the same project and environment) about those subjects. OpenVibe.Events rewrites each target into a tombstone (events.tombstone-payload@1) in the transaction that stores the directive. Naming another source's event is 403 events.redaction_not_allowed (the whole batch is refused); a malformed directive is 422 events.invalid_redaction. An event that carries a directive is never redacted itself.
 */
export interface RedactionDirective {
  /**
   * Events to redact by id. Duplicates are ignored.
   *
   * @minItems 1
   * @maxItems 1000
   */
  event_ids?: [string, ...string[]];
  /**
   * Envelope subject.type of the events to redact (chat_message, post…). Goes with subject_ids.
   */
  subject_type?: string;
  /**
   * Envelope subject.id values; every not-yet-redacted event of the same source about each one is redacted.
   *
   * @minItems 1
   * @maxItems 1000
   */
  subject_ids?: [string, ...string[]];
}

/** events.tombstone-payload@1.0.0 (owner: events) */
/**
 * The payload of a redacted event (ADR-026). OpenVibe.Events replaces the original payload with this and the actor with the producer itself ({ type: service, id: <source> }, or the app); event_id, seq, event_type, version, subject, timestamp and visibility stay. Every read path serves it from then on: pull, GET by id, SSE replay, queued deliveries and DLQ replays. A consumer checks payload.redacted before validating a payload against its event type's schema.
 */
export interface TombstonePayload {
  redacted: true;
  redacted_at: string;
  /**
   * The event_id of the redacting event; an operator label (e.g. backfill) when OpenVibe.Events redacted by script.
   */
  redacted_by: string;
}

/** chat.message.deleted@1.0.0 (owner: chat) */
/**
 * chat.message.deleted v1 (OpenVibe.Chat server/db/database.js _announceDeleted). Public messages were deleted: by a moderator, through Live's bridge, the author's or an anon's history, a time-range purge or the auto-delete sweep. Envelope: subject { type: chat_message, id: <first id> }, visibility public, priority important, actor service:chat. One event per 500 ids. Carries only ids, never the text, the author or who deleted it; payload.redacts makes OpenVibe.Events tombstone the chat.message.created of each id.
 */
export interface ChatMessageDeletedPayload {
  /**
   * Chat message ids (the id in chat.message.created).
   *
   * @minItems 1
   * @maxItems 500
   */
  message_ids: [number, ...number[]];
  redacts: RedactionDirective;
}

/** sources.item.created@1.0.0 (owner: sources) */
/**
 * sources.item.created v1 (OpenVibe.Sources server/items.js ingest → itemEvent). A successful fetch, or a manual entry, produced an item Sources had not seen (revision 1). A summary only: consumers fetch the full sources.item@1 with sources.item.read. Envelope: subject { type: item, id: <item_id>, revision }, visibility internal, priority important, actor service:sources.
 */
